101	pub(crate) fn read_regime_day(dir: &Path, day: &str, need_mid: bool) -> anyhow::Result<RegimeDay> {
102	    let path = dir.join(format!("{day}.csv"));
103	    let mut r = csv::ReaderBuilder::new()
104	        .from_path(&path)
105	        .map_err(|e| anyhow::anyhow!("--regime-from: {}: {e}", path.display()))?;
106	    let header = r.headers()?.clone();
107	    let idx = |name: &str| -> anyhow::Result<usize> {
108	        header
109	            .iter()
110	            .position(|h| h == name)
111	            .ok_or_else(|| anyhow::anyhow!("{}: нет колонки {name}", path.display()))
112	    };
113	    let opt = |name: &str| -> anyhow::Result<Option<usize>> {
114	        match header.iter().position(|h| h == name) {
115	            Some(i) => Ok(Some(i)),
116	            None if need_mid => anyhow::bail!(
117	                "{}: нет колонки {name} — оси btc2h/btc3h требуют режим, пересчитанный regime.py",
118	                path.display()
119	            ),
120	            None => Ok(None),
121	        }
122	    };
123	    let cols = [
124	        Some(idx("minute_ms")?),
125	        Some(idx("pool_ret_1h_bps")?),
126	        Some(idx("pool_ret_4h_bps")?),
127	        Some(idx("btc_ret_1h_bps")?),
128	        Some(idx("btc_ret_4h_bps")?),
129	        opt("btc_ret_2h_bps")?,
130	        opt("btc_ret_3h_bps")?,
131	    ];
132	    let mut out = RegimeDay::new();
133	    for rec in r.records() {
134	        let rec = rec?;
135	        let minute: i64 = rec
136	            .get(cols[0].expect("minute_ms обязателен"))
137	            .ok_or_else(|| anyhow::anyhow!("{}: короткая строка", path.display()))?
138	            .parse()?;
139	        let mut vals = [None; 6];
140	        for (k, c) in cols[1..].iter().enumerate() {
141	            let Some(c) = c else { continue };
142	            let v = rec.get(*c).unwrap_or("");
143	            vals[k] = if v.is_empty() {
144	                None
145	            } else {
146	                Some(v.parse::<f64>()?)
147	            };
148	        }
149	        out.insert(minute, vals);
150	    }
151	    Ok(out)
152	}
